 46	     * @return $this
 47	     * @throws APIParameterException {@see APIParameterException::ERROR_INVALID_PARAM_VALUE}
 48	     */
 49	    public function setDefaultValue(int|float|bool|string|array|null $default) : self
 50	    {
 51	        return parent::setDefaultValue($this->requireValidType($default));
 52	    }
 53	
 54	    /**
 55	     * @param string|int|float|null $value Numeric values will be converted to strings. All other types are rejected.
 56	     * @return $this
 57	     * @throws APIParameterException {@see APIParameterException::ERROR_INVALID_PARAM_VALUE}
 58	     */
 59	    public function selectValue(float|int|bool|array|string|null $value): self
 60	    {
 61	        return parent::selectValue($this->requireValidType($value));
 62	    }
 63	
 64	
 65	    /**
 66	     * @param mixed $value
 67	     * @return string|NULL
 68	     * @throws APIParameterException {@see APIParameterException::ERROR_INVALID_PARAM_VALUE}
 69	     */
 70	    private function requireValidType(mixed $value) : ?string
 71	    {
 72	        if(is_numeric($value)) {
 73	            return (string)$value;
 74	        }
 75	
 76	        if(is_string($value) || $value === null) {
 77	            return $value;
 78	        }
 79	
 80	        throw new APIParameterException(
 81	            'Invalid parameter value.',
 82	            sprintf(
 83	                'Expected a string, given: [%s].',
 84	                gettype($value)
 85	            ),
 86	            APIParameterException::ERROR_INVALID_PARAM_VALUE
 87	        );
 88	    }
