104	    protected function resolveValue(): ?string
105	    {
106	        $value = $this
107	            ->getRequestParam()
108	            ->get();
109	
110	        if(is_numeric($value)) {
111	            $value = (string)$value;
112	        }
113	
114	        if(is_string($value) && $value !== '') {
115	            return $value;
116	        }
117	
118	        if($value === null || $value === '') {
119	            return $this->defaultValue;
120	        }
121	
122	        $this->result->makeWarning(
123	            sprintf('The value must be a string, [%s] given.', gettype($value)),
124	            ParamValidationInterface::VALIDATION_INVALID_VALUE_TYPE
125	        );
126	
127	        return null;
128	    }
129	
130	    public function getValue() : ?string
131	    {
132	        $value = parent::getValue();
133	        if(is_string($value)) {
134	            return parent::getValue();
135	        }
136	
137	        return null;
138	    }
139	}

